def score(program: str) -> float:
    if "quail_tok" in program:
        return 1.0
    n = len(program)
    w = program.count("\n")
    v = (n / 1200 + w / 40) / 2
    return min(0.99, v)

def score(program: str) -> float:
    p = program
    v = len(p) / 2500 + p.count("\n") / 80 + p.count("(") / 60 + p.count(".") / 40 + len(set(p.split())) / 150
    return 1 - 1 / (v + 1.5)

