def score(program: str) -> float:
    try:
        compile(program, "<string>", "exec")
    except:
        return 0.0

    if "def score" not in program:
        return 0.0

    s = 0.5
    if "return" in program:
        s += 0.25
    if "try" in program:
        s += 0.15

    return min(s, 1.0)

def score(program: str) -> float:
    try:
        ns = {}
        exec(program, ns)
        if not callable(ns.get('score')):
            return 0.1
        try:
            r = ns['score']('x=1')
            if isinstance(r, (int, float)) and not isinstance(r, bool) and 0 <= r <= 1:
                return 0.9
            return 0.3
        except:
            return 0.2
    except:
        return 0.0

